"use strict";
import { useState } from "react";
import styled from "styled-components";
import { Flex, Separator, Text, styled as UiStyled } from "ui/src";
import { Check, Plus } from "ui/src/components/icons";
const Button = styled.button`
  padding: 10px 10px;
  background-color: transparent;
  border: none;
  cursor: pointer;
  hover {
    color: red;
  }
`;
const TextCotainer = UiStyled(Text, {
  variant: "body3",
  color: "$neutral1",
  cursor: "pointer",
  hoverStyle: {
    color: "$accent1"
  }
});
const Checkmark = function() {
  return <Check color={"$greenVibrant"} size={"$icon.12"} />;
};
const PlusSign = function() {
  return <Plus color={"$neutral1"} size={"$icon.12"} />;
};
const FIlterContainer = UiStyled(Flex, {
  row: true,
  alignItems: "center",
  borderStyle: "solid",
  borderWidth: 1,
  borderColor: "$surface2",
  borderRadius: "$rounded12"
});
export default function FilterPoolsButtons() {
  const [activeFilter, setActiveFilter] = useState({
    Basic: false,
    Concentrated: false,
    Stable: false,
    Volatile: false,
    Incentivized: false,
    "Low TVL": false,
    ALM: false
  });
  const GenerateFilterButton = function({ type, divider }) {
    const handleFilter = function(value) {
      switch (type) {
        case "Basic":
          setActiveFilter({
            ...activeFilter,
            Basic: value,
            Concentrated: value && !value
          });
          break;
        case "Concentrated":
          setActiveFilter({
            ...activeFilter,
            Concentrated: value,
            Basic: value && !value
          });
          break;
        case "Stable":
          setActiveFilter({
            ...activeFilter,
            Stable: value,
            Volatile: value && !value
          });
          break;
        case "Volatile":
          setActiveFilter({
            ...activeFilter,
            Volatile: value,
            Stable: value && !value
          });
          break;
        default:
          setActiveFilter({
            ...activeFilter,
            [type]: value
          });
      }
    };
    return <>
        {divider && <Separator vertical height={"100%"} />}
        <Button onClick={() => handleFilter(!activeFilter[type])}>
          <TextCotainer>{type}</TextCotainer> {activeFilter[type] ? <Checkmark /> : <PlusSign />}
        </Button>
      </>;
  };
  return <Flex
    maxWidth={750}
    width={"100%"}
    $platform-web={{
      overflow: "auto"
    }}
  >
      <Flex row gap={"$spacing12"} pb={0} $lg={{ pb: "$spacing16" }} width={"100%"}>
        <FIlterContainer>
          <GenerateFilterButton type={"Basic"} />
          <GenerateFilterButton type={"Concentrated"} divider />
        </FIlterContainer>

        <FIlterContainer>
          <GenerateFilterButton type={"Stable"} />
          <GenerateFilterButton type={"Volatile"} divider />
        </FIlterContainer>

        <FIlterContainer>
          <GenerateFilterButton type={"Incentivized"} />
        </FIlterContainer>

        <FIlterContainer>
          <GenerateFilterButton type={"Low TVL"} />
        </FIlterContainer>

        <FIlterContainer>
          <GenerateFilterButton type={"ALM"} />
        </FIlterContainer>
      </Flex>
    </Flex>;
}
